/**
 * AiCoreMessage
 *
 * A message in the conversation history following Vercel AI SDK patterns
 */
export type AiCoreMessage = {
    role: 'user' | 'assistant' | 'system' | 'tool';
    content: string;
    metadata?: {
        isConsideredSystemMessage?: boolean;
        usage?: TokenUsage;
        finishReason?: string;
        /**
         * ISO 8601 timestamp when the message was created
         */
        timestamp?: Date;
        /**
         * Tool calls made to generate the message
         */
        toolCalls?: Array<ToolCall>;
        /**
         * Reasoning text for the message
         */
        reasonning?: string;
    };
};

/**
 * AiStreamEvent
 *
 * SSE event for AI text streaming with tool support
 */
export type AiStreamEvent = {
    type: 'chunk';
    text: string;
} | {
    type: 'tool-call';
    toolCallId: string;
    toolName: string;
    args: {
        [key: string]: unknown;
    };
} | {
    type: 'tool-result';
    toolCallId: string;
    toolName: string;
    result: unknown;
} | {
    type: 'done';
    fullText: string;
    /**
     * AiStreamUsage
     *
     * Token usage information for the stream
     */
    usage?: {
        promptTokens: number;
        completionTokens: number;
        totalTokens: number;
    };
    finishReason?: string;
} | {
    type: 'error';
    message: string;
};

